-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_attendance AS SELECT attendance.link_to_event AS link_to_event, attendance.link_to_member AS link_to_member, event.event_name AS event_name, event.event_date AS event_date, event.type AS type, event.notes AS notes, event.location AS location, event.status AS status, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major FROM attendance LEFT JOIN event ON attendance.link_to_event = event.event_id LEFT JOIN member ON attendance.link_to_member = member.member_id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_budget AS SELECT budget.budget_id AS budget_id, budget.category AS category, budget.spent AS spent, budget.remaining AS remaining, budget.amount AS amount, budget.event_status AS event_status, event.event_name AS event_name, event.event_date AS event_date, event.type AS type, event.notes AS notes, event.location AS location, event.status AS status FROM budget LEFT JOIN event ON budget.link_to_event = event.event_id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_expense AS SELECT expense.expense_id AS expense_id, expense.expense_description AS expense_description, expense.expense_date AS expense_date, expense.cost AS cost, expense.approved AS approved, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major, budget.category AS category, budget.spent AS spent, budget.remaining AS remaining, budget.amount AS amount, budget.event_status AS event_status, event.event_name AS event_name, event.event_date AS event_date, event.type AS type, event.notes AS notes, event.location AS location, event.status AS status FROM expense LEFT JOIN member ON expense.link_to_member = member.member_id LEFT JOIN budget ON expense.link_to_budget = budget.budget_id LEFT JOIN event ON budget.link_to_event = event.event_id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_income AS SELECT income.income_id AS income_id, income.date_received AS date_received, income.amount AS amount, income.source AS source, income.notes AS notes, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major FROM income LEFT JOIN member ON income.link_to_member = member.member_id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_member AS SELECT member.member_id AS member_id, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, zip_code.type AS type, zip_code.city AS city, zip_code.county AS county, zip_code.state AS state, zip_code.short_state AS short_state, major.major_name AS major_name, major.department AS department, major.college AS college FROM member LEFT JOIN zip_code ON member.zip = zip_code.zip_code LEFT JOIN major ON member.link_to_major = major.major_id;
